css:
.print-format { padding: 0 !important; margin: 0 !important; max-width: 80mm; }
.rs { width: 72mm; margin: 0 auto; font-family: monospace, sans-serif; font-size: 12px; color: #000; }
.rs-c { text-align: center; }
.rs-r { text-align: right; white-space: nowrap; }
.rs-b { font-weight: bold; }
.rs-l { font-size: 14px; }
.rs-s { font-size: 10px; }
.rs-hr { border-top: 1px dashed #000; margin: 5px 0; }
.rs-t { width: 100%; border-collapse: collapse; font-size: inherit; }
.rs-t td { padding: 1px 0; vertical-align: top; }
.rs-save { border: 1px solid #000; padding: 3px 4px; border-radius: 3px; }
@page { size: 80mm auto; margin: 2mm; }

html:
{%- set cur = doc.currency -%}
{%- set sv = posa_savings(doc) -%}
{%- macro m(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{%- endmacro -%}
<div class="rs">
  <div class="rs-c rs-b rs-l">{{ doc.company }}</div>
  {%- if doc.company_address_display %}<div class="rs-c rs-s">{{ doc.company_address_display }}</div>{% endif %}
  <div class="rs-c rs-b">{{ _("RETURN") if doc.is_return else _("SALES RECEIPT") }}</div>
  <div class="rs-hr"></div>
  <table class="rs-t">
    <tr><td>{{ _("Receipt") }}</td><td class="rs-r">{{ doc.name }}</td></tr>
    <tr><td>{{ _("Date") }}</td><td class="rs-r">{{ frappe.utils.formatdate(doc.posting_date) }} {{ (doc.posting_time or "")[:5] }}</td></tr>
    {%- if doc.customer_name and doc.customer_name != doc.customer %}<tr><td>{{ _("Customer") }}</td><td class="rs-r">{{ doc.customer_name }}</td></tr>
    {%- elif doc.customer %}<tr><td>{{ _("Customer") }}</td><td class="rs-r">{{ doc.customer }}</td></tr>{% endif %}
    <tr><td>{{ _("Cashier") }}</td><td class="rs-r">{{ frappe.get_fullname(doc.owner) }}</td></tr>
  </table>
  <div class="rs-hr"></div>
  <table class="rs-t">
    {%- for it in doc.items %}
    <tr><td colspan="2">{{ it.item_name }}{% if it.posa_sm_markdown %} <b>({{ _("Reduced") }})</b>{% endif %}</td></tr>
    <tr class="rs-s"><td>&nbsp; {{ frappe.utils.flt(it.qty, 3) }} {{ it.uom }} x {{ m(it.rate) }}{% if it.price_list_rate and it.price_list_rate > it.rate %} <s>{{ m(it.price_list_rate) }}</s>{% endif %}</td>
      <td class="rs-r">{{ m(it.amount) }}</td></tr>
    {%- endfor %}
  </table>
  <div class="rs-hr"></div>
  <table class="rs-t">
    <tr><td>{{ _("Total") }}</td><td class="rs-r">{{ m(doc.total) }}</td></tr>
    {%- if doc.discount_amount %}<tr><td>{{ _("Discount") }}</td><td class="rs-r">-{{ m(doc.discount_amount) }}</td></tr>{% endif %}
    {%- for t in doc.taxes %}<tr><td>{{ t.description }}</td><td class="rs-r">{{ m(t.tax_amount) }}</td></tr>{% endfor %}
    {%- if doc.rounding_adjustment %}<tr><td>{{ _("Rounding") }}</td><td class="rs-r">{{ m(doc.rounding_adjustment) }}</td></tr>{% endif %}
    <tr class="rs-b rs-l"><td>{{ _("Grand Total") }}</td><td class="rs-r">{{ m(doc.rounded_total or doc.grand_total) }}</td></tr>
    {%- for p in doc.payments if p.amount %}<tr><td>{{ p.mode_of_payment }}</td><td class="rs-r">{{ m(p.amount) }}</td></tr>{% endfor %}
    {%- if doc.change_amount %}<tr><td>{{ _("Change") }}</td><td class="rs-r">{{ m(doc.change_amount) }}</td></tr>{% endif %}
  </table>
  {%- if sv.total and sv.total > 0 %}
  <div class="rs-hr"></div>
  <div class="rs-save">
    <div class="rs-c rs-b rs-l">{{ _("You saved") }} {{ m(sv.total) }}</div>
    <table class="rs-t rs-s">
      {%- if sv.offers %}<tr><td>{{ _("Offers") }}</td><td class="rs-r">{{ m(sv.offers) }}</td></tr>{% endif %}
      {%- if sv.deals %}<tr><td>{{ _("Deals") }}</td><td class="rs-r">{{ m(sv.deals) }}</td></tr>{% endif %}
      {%- if sv.markdowns %}<tr><td>{{ _("Reduced items") }}</td><td class="rs-r">{{ m(sv.markdowns) }}</td></tr>{% endif %}
      {%- if sv.discounts %}<tr><td>{{ _("Discounts") }}</td><td class="rs-r">{{ m(sv.discounts) }}</td></tr>{% endif %}
      {%- if sv.mrp %}<tr><td>{{ _("Below MRP") }}</td><td class="rs-r">{{ m(sv.mrp) }}</td></tr>{% endif %}
    </table>
  </div>
  {%- endif %}
  {%- if doc.get("fbr_invoice_no") %}
  <div class="rs-hr"></div>
  <div class="rs-c rs-s">{{ _("FBR Invoice") }} {{ doc.fbr_invoice_no }}</div>
  {%- endif %}
  <div class="rs-hr"></div>
  <div class="rs-c rs-s">{{ _("Thank you for shopping with us") }}</div>
</div>
